insert into natural_english_private.catalogue(module,senses,questions) values
('advanced-native-1958', '["phrase"]'::jsonb, '{"advanced-native-1958-v1-audio":{"type":"mc","answers":["There was an urge to click, but no order had been made before the size check."],"options":["The speaker had asked a friend to place the order while the size was being checked.","The speaker had chosen the size in advance and felt no temptation when the print appeared.","There was an urge to click, but no order had been made before the size check.","The speaker had bought the print and was checking how to exchange it for another size."]},"advanced-native-1958-v2-reply":{"type":"mc","answers":["I felt tempted to click without yet completing a purchase.","The urge was present, while the decision still needed a practical check.","I closed the page instead of treating the first impulse as my final choice.","I had itchy fingers, but I paused before ordering to check the size I wanted."],"options":["I felt tempted to click without yet completing a purchase.","The urge was present, while the decision still needed a practical check.","I closed the page instead of treating the first impulse as my final choice.","I had itchy fingers, but I paused before ordering to check the size I wanted."]},"advanced-native-1958-v1-scene":{"type":"mc","answers":["A quick planned purchase does not by itself show itchy fingers; the account gives preparation rather than a restless urge to buy."],"options":["A quick planned purchase does not by itself show itchy fingers; the account gives preparation rather than a restless urge to buy.","The account describes him abandoning the list because an unexpected display tempted him.","His speed shows that he had not considered the cost before arriving at the shop."]},"advanced-native-1958-v1-contrast":{"type":"mc","answers":["人物已完成每個想買的訂單。"],"options":["人物很想立即點選或購買。","人物已完成每個想買的訂單。","上下文可說明手指意象指向甚麼動作。"]},"advanced-native-1958-v1-branch":{"type":"mc","answers":["I had itchy fingers, but I have not ordered; I am checking the size before deciding whether to go ahead."],"options":["I thought closing the page meant the shop had cancelled an order I had placed.","I had itchy fingers, but I have not ordered; I am checking the size before deciding whether to go ahead.","The print must already be on its way, then; I will clear a space for its delivery."]},"advanced-native-1958-v1-final":{"type":"open","answers":["I have itchy fingers over this workshop, but I remember you asked me not to enrol you. Would you like the details to look at yourself, with the decision entirely yours and no booking made on your behalf?","These itchy fingers are mine, not permission to use the shared account for your place. I can send the course details if you want, but I will leave any decision to enrol with you."],"options":[]}}'::jsonb),
('advanced-native-1959', '["phrase"]'::jsonb, '{"advanced-native-1959-v1-audio":{"type":"mc","answers":["Some letters became readable from home, while volunteers still helped explain the collection."],"options":["The online copies replaced the letters with a summary that omitted their dates.","Some letters became readable from home, while volunteers still helped explain the collection.","The archive made every letter available and no longer needed anyone to explain its gaps.","Residents had to visit the centre before they could read any selected letter."]},"advanced-native-1959-v2-reply":{"type":"mc","answers":["It became a library without walls by letting them read selected materials beyond the building.","The reading resources could reach people at home as well as at the centre.","Access to part of the collection no longer depended on being in that room.","The physical centre and the online copies offered connected ways to read the letters."],"options":["It became a library without walls by letting them read selected materials beyond the building.","The reading resources could reach people at home as well as at the centre.","Access to part of the collection no longer depended on being in that room.","The physical centre and the online copies offered connected ways to read the letters."]},"advanced-native-1959-v1-scene":{"type":"mc","answers":["The shared boxes and support can form a library without walls even though the access route is not a website."],"options":["Without a website, the account describes resources available only inside one library building.","The boxes remove the need to know who can answer questions about the material.","The shared boxes and support can form a library without walls even though the access route is not a website."]},"advanced-native-1959-v1-contrast":{"type":"mc","answers":["每份材料都已核實，而且每人都能同樣容易使用。"],"options":["每份材料都已核實，而且每人都能同樣容易使用。","更多情境可交代資源怎樣到達讀者。","資源被形容為不受單一建築限制。"]},"advanced-native-1959-v1-branch":{"type":"mc","answers":["A library without walls can still need guides; the copies give access, but the volunteers help readers understand the missing dates."],"options":["A library without walls can still need guides; the copies give access, but the volunteers help readers understand the missing dates.","I would leave readers to infer the dates because putting the copies online should provide that explanation.","I thought the archive had published a complete collection with every date confirmed."]},"advanced-native-1959-v1-final":{"type":"open","answers":["Our archive is a library without walls, and you can explore it in a way that works for you. Visit the centre for a printed selection or ask a volunteer to help you find the letters, instead of needing to use the code on your own.","A library without walls should offer more than one doorway into its collection. You can collect printed copies at the centre or speak to a volunteer for help; a phone is not the only way to begin."],"options":[]}}'::jsonb),
('advanced-native-1962', '["phrase"]'::jsonb, '{"advanced-native-1962-v1-audio":{"type":"mc","answers":["The range of people and evidence widened even though the students remained in their usual room."],"options":["Moving the desks was described as the only change in their learning experience.","The range of people and evidence widened even though the students remained in their usual room.","They left their classroom and completed the project entirely inside the curator’s museum.","The project kept them from asking anyone outside their class about the objects."]},"advanced-native-1962-v2-reply":{"type":"mc","answers":["They were not stuck inside one classroom because they could question someone and examine evidence from beyond it.","The remote curator added a perspective the class could consult directly.","The students compared local objects with material from another collection.","The room stayed the same while the sources available for their questions changed."],"options":["They were not stuck inside one classroom because they could question someone and examine evidence from beyond it.","The remote curator added a perspective the class could consult directly.","The students compared local objects with material from another collection.","The room stayed the same while the sources available for their questions changed."]},"advanced-native-1962-v1-scene":{"type":"mc","answers":["The class is physically outdoors, but the unchanged worksheet offers no new source or question; being stuck inside one classroom is not just about location."],"options":["The class is physically outdoors, but the unchanged worksheet offers no new source or question; being stuck inside one classroom is not just about location.","The account gives the students direct access to a remote specialist and another collection.","The outdoor location establishes that the worksheet now asks different questions."]},"advanced-native-1962-v1-contrast":{"type":"mc","answers":["他們所做的每項活動都比原有課堂更好。"],"options":["他們所做的每項活動都比原有課堂更好。","需要情境說明實際可接觸甚麼。","說話者在否定某種單一課室的限制。"]},"advanced-native-1962-v1-branch":{"type":"mc","answers":["They need not be stuck inside one classroom just because the desks stay there; their questions can reach the curator and the other collection."],"options":["They need not be stuck inside one classroom just because the desks stay there; their questions can reach the curator and the other collection.","I would describe the conversation as entirely within the class because the students did not travel to the museum.","I thought the only change was where the desks were placed in the room."]},"advanced-native-1962-v1-final":{"type":"open","answers":["Missing the visit need not leave our groupmate stuck inside one classroom: could they choose a question for the teacher to pass on and receive the repairer’s reply? We can include their interpretation when we analyse the visit together.","Let us avoid leaving anyone stuck inside one classroom just because they cannot attend that day. I suggest asking our groupmate to prepare the question, sharing the reply with them and giving everyone a part in the follow-up discussion."],"options":[]}}'::jsonb),
('advanced-native-1963', '["phrase"]'::jsonb, '{"advanced-native-1963-v1-audio":{"type":"mc","answers":["There were more revisions, while improved understanding still needed checking."],"options":["The teacher wanted fewer opportunities for pairs to revise their explanations.","The trial had already shown that immediate feedback prevented students from revising.","There were more revisions, while improved understanding still needed checking.","The trial had confirmed better understanding in every subject taught at the school."]},"advanced-native-1963-v2-reply":{"type":"mc","answers":["Whether students can explain the idea better after revising.","What the additional revisions changed in the students’ understanding.","Whether the observed activity connects to the learning aim the teacher set.","Whether the feedback can turbocharge education through better understanding, rather than only more revisions."],"options":["Whether students can explain the idea better after revising.","What the additional revisions changed in the students’ understanding.","Whether the observed activity connects to the learning aim the teacher set.","Whether the feedback can turbocharge education through better understanding, rather than only more revisions."]},"advanced-native-1963-v1-scene":{"type":"mc","answers":["Faster page completion alone does not show that the programme can turbocharge education through stronger learning."],"options":["The completion timer already measures whether students can apply the concept in a new task.","The account describes a successful application task rather than only faster page completion.","Faster page completion alone does not show that the programme can turbocharge education through stronger learning."]},"advanced-native-1963-v1-contrast":{"type":"mc","answers":["工具已在每個情境證實能改善所有學生的理解。"],"options":["說話者認為工具有大幅加強學習的可能。","工具已在每個情境證實能改善所有學生的理解。","需要知道它透過甚麼方式影響學習。"]},"advanced-native-1963-v1-branch":{"type":"mc","answers":["We hope it can turbocharge education, but we should report the extra revisions as observed and check understanding separately."],"options":["I would use the revision total as the measure of understanding without asking what the changes meant.","I thought the trial had already tested how students applied the idea in a different task.","We hope it can turbocharge education, but we should report the extra revisions as observed and check understanding separately."]},"advanced-native-1963-v1-final":{"type":"open","answers":["If we want to know whether this tool can turbocharge education, let us give students a new problem a week later and ask them to explain their reasoning. Their answers would give us evidence of applying the idea, rather than just finishing pages quickly.","The tool may help turbocharge education, but our follow-up should test what students can do without the original example. I suggest a new task next week, with time for students to explain why their chosen approach fits."],"options":[]}}'::jsonb),
('advanced-native-1964', '["phrase"]'::jsonb, '{"advanced-native-1964-v1-audio":{"type":"mc","answers":["The volume made the rehearsal time hard to find, while some posts could still matter to others."],"options":["Every post had been checked and found false by the club.","The speaker found the rehearsal detail immediately and was describing only loud sounds in the room.","The old photographs were the only information the speaker had been looking for.","The volume made the rehearsal time hard to find, while some posts could still matter to others."]},"advanced-native-1964-v2-reply":{"type":"mc","answers":["The useful detail was present but did not stand out for me.","The difficulty was finding the relevant time among material serving different interests.","It was a sea of noise around the rehearsal detail I needed to find.","Many competing posts made one practical message hard to locate."],"options":["The useful detail was present but did not stand out for me.","The difficulty was finding the relevant time among material serving different interests.","It was a sea of noise around the rehearsal detail I needed to find.","Many competing posts made one practical message hard to locate."]},"advanced-native-1964-v1-scene":{"type":"mc","answers":["The notes can still feel like a sea of noise if the relevant commitment is hard to distinguish, even in a quiet room."],"options":["The account says the difficulty is hearing the person speaking at the door.","The notes can still feel like a sea of noise if the relevant commitment is hard to distinguish, even in a quiet room.","The term applies only to audible speech, so written notes cannot be described as a sea of noise."]},"advanced-native-1964-v1-contrast":{"type":"mc","answers":["每則內容對每位讀者都必定虛假且沒有用途。"],"options":["頁面內容令說話者難以分辨重點。","每則內容對每位讀者都必定虛假且沒有用途。","更多情境可說明說話者想找甚麼。"]},"advanced-native-1964-v1-branch":{"type":"mc","answers":["They made the feed a sea of noise for my time check, but irrelevant to that question does not mean false or useless to everyone."],"options":["I would use the difficulty of finding the time as evidence that the old photos are inaccurate.","I thought the speaker’s purpose was to judge which photograph had the best composition.","They made the feed a sea of noise for my time check, but irrelevant to that question does not mean false or useless to everyone."]},"advanced-native-1964-v1-final":{"type":"open","answers":["Your message was lost to me in a sea of noise, but I am sorry that I replied without reading it properly and made your concern feel dismissed. Would you be willing to talk privately, so I can listen to what you actually wanted to say?","I treated the thread as a sea of noise instead of noticing that you were asking for help, and the smiling reply was my mistake. I am sorry; if you want to talk privately, I would like to hear you without rushing another response."],"options":[]}}'::jsonb),
('advanced-native-1965', '["phrase"]'::jsonb, '{"advanced-native-1965-v1-audio":{"type":"mc","answers":["Audience choices were separated, while contributors’ understanding still needed checking."],"options":["Audience choices were separated, while contributors’ understanding still needed checking.","Choosing family-only sharing automatically approved public display as well.","The group had already confirmed that every contributor understood all the choices.","The project had stopped accepting photos for any form of shared viewing."]},"advanced-native-1965-v2-reply":{"type":"mc","answers":["The choices defined who could see the material, while their clarity still needed review.","It was putting up guardrails by separating family-only viewing from public display.","Contributors could choose a narrower audience without also approving public use.","A separate check was needed before photographs could be displayed publicly."],"options":["The choices defined who could see the material, while their clarity still needed review.","It was putting up guardrails by separating family-only viewing from public display.","Contributors could choose a narrower audience without also approving public use.","A separate check was needed before photographs could be displayed publicly."]},"advanced-native-1965-v1-scene":{"type":"mc","answers":["They can put up guardrails for shared use without banning borrowing; these rules define access and handover."],"options":["The account describes a decision to keep the equipment unused by every member.","The record is only for the final return, so intermediate handovers between members do not need to be recorded.","They can put up guardrails for shared use without banning borrowing; these rules define access and handover."]},"advanced-native-1965-v1-contrast":{"type":"mc","answers":["每項風險都已消失，無須再了解使用情況。"],"options":["要用情境交代保護甚麼及怎樣限制。","小組正在設立某種保護界限。","每項風險都已消失，無須再了解使用情況。"]},"advanced-native-1965-v1-branch":{"type":"mc","answers":["Putting up guardrails is a start, but we still need to ask whether contributors understand the audience choices before relying on them."],"options":["Putting up guardrails is a start, but we still need to ask whether contributors understand the audience choices before relying on them.","I would treat the presence of the choices as confirmation that every contributor has understood them.","I thought the group had replaced all sharing choices with a ban on submitting photographs."]},"advanced-native-1965-v1-final":{"type":"open","answers":["We are putting up guardrails around the live settings, so only trained operators change them before the performance. You can still develop a plan in the practice copy and ask for feedback, which gives you a way to learn without changing the live setup.","Putting up guardrails here means keeping live changes with trained operators, not closing off your ideas. Please try your design in the separate practice copy, then we can discuss the choices before anything is considered for the performance."],"options":[]}}'::jsonb),
('advanced-native-1966', '["phrase"]'::jsonb, '{"advanced-native-1966-v1-audio":{"type":"mc","answers":["An introduction to the technical terms needed for the notes."],"options":["More specialist notes to replace an introductory explanation of the vocabulary.","An introduction to the technical terms needed for the notes.","Confirmation that the volunteers have already mastered the technical terminology.","A guide to finding the links after the technical terms have already been explained."]},"advanced-native-1966-v2-reply":{"type":"mc","answers":["People may wander into places they are not ready for when they open technical notes without knowing the terms.","Access to the page does not supply the knowledge needed to understand it.","The link can lead newcomers beyond the vocabulary they have learnt so far.","We want to connect the available material with the preparation it actually requires."],"options":["People may wander into places they are not ready for when they open technical notes without knowing the terms.","Access to the page does not supply the knowledge needed to understand it.","The link can lead newcomers beyond the vocabulary they have learnt so far.","We want to connect the available material with the preparation it actually requires."]},"advanced-native-1966-v1-scene":{"type":"mc","answers":["Being new to the site does not establish that he will wander into places he is not ready for; his relevant knowledge also matters."],"options":["His first visit establishes that the material is beyond his understanding.","Being new to the site does not establish that he will wander into places he is not ready for; his relevant knowledge also matters.","The account says he has not yet learnt the key terms in the notes."]},"advanced-native-1966-v1-contrast":{"type":"mc","answers":["他們已受到某種具體且永久的傷害。"],"options":["可以再問準備不足具體指甚麼。","他們可能接觸尚未準備好處理的內容。","他們已受到某種具體且永久的傷害。"]},"advanced-native-1966-v1-branch":{"type":"mc","answers":["They may wander into places they are not ready for, so let us explain the terms before treating access as understanding."],"options":["They may wander into places they are not ready for, so let us explain the terms before treating access as understanding.","I assumed being given the link meant the vocabulary had already been taught.","I would start with the specialist examples and leave the unfamiliar terms for newcomers to work out on their own."]},"advanced-native-1966-v1-final":{"type":"open","answers":["I could wander into places I am not ready for if I take the chair before understanding the discussion rules and the concerns involved. Could I observe one session and speak with the current chair before confirming the role?","I would like to learn, but I do not want to wander into places I am not ready for by accepting this responsibility before I know the procedure. Please let me observe a discussion and ask the chair about the different concerns before I decide."],"options":[]}}'::jsonb),
('advanced-native-1967', '["phrase"]'::jsonb, '{"advanced-native-1967-v1-audio":{"type":"mc","answers":["Continuous observation was replaced by independent drafting and a review of marked uncertainties."],"options":["The learner still needed approval for every word before entering it.","The review happened before the learner had identified any uncertain entry.","Continuous observation was replaced by independent drafting and a review of marked uncertainties.","The tutor stopped allowing questions as soon as independent drafting began."]},"advanced-native-1967-v2-reply":{"type":"mc","answers":["I produce a draft first and discuss the uncertain parts afterwards.","We have separated my initial work from the tutor’s review.","There is still support, but not approval before each word I enter.","She no longer needs to look over my shoulder for every record; I bring marked questions to a later review."],"options":["I produce a draft first and discuss the uncertain parts afterwards.","We have separated my initial work from the tutor’s review.","There is still support, but not approval before each word I enter.","She no longer needs to look over my shoulder for every record; I bring marked questions to a later review."]},"advanced-native-1967-v1-scene":{"type":"mc","answers":["Here he checks behind himself; that is different from a tutor looking over another person’s shoulder to monitor the work."],"options":["Here he checks behind himself; that is different from a tutor looking over another person’s shoulder to monitor the work.","The account says he stood beside a trainee and checked each entry.","His concern is described as another person’s unfinished work, rather than someone following him."]},"advanced-native-1967-v1-contrast":{"type":"mc","answers":["她已拒絕在任何情況下再提供協助。"],"options":["她已拒絕在任何情況下再提供協助。","可以問我們改用了甚麼覆核方式。","她不再逐步緊盯我正在做的工作。"]},"advanced-native-1967-v1-branch":{"type":"mc","answers":["She need not look over my shoulder continuously for me to mark uncertainty and ask at the agreed review."],"options":["I would ask for approval before every word again, rather than use the review arrangement we agreed.","She need not look over my shoulder continuously for me to mark uncertainty and ask at the agreed review.","I assumed working alone meant uncertain entries no longer needed to be marked."]},"advanced-native-1967-v1-final":{"type":"open","answers":["I appreciate the offer to help, but I would rather you did not look over my shoulder while I write this private memory. Could I choose a passage to share with you once I have decided what I want others to read?","Please give me some privacy instead of looking over my shoulder as I draft this family account. I value your advice and will ask for it on a passage I am comfortable sharing."],"options":[]}}'::jsonb),
('advanced-native-1968', '["phrase"]'::jsonb, '{"advanced-native-1968-v1-audio":{"type":"mc","answers":["Calm explanation and questions, while keeping clear rules for the practice."],"options":["Removing the agreed drill so nobody needs to learn the cue.","Using embarrassment as the main way to explain the drill.","Postponing the explanation until the beginners can perform the cue without help.","Calm explanation and questions, while keeping clear rules for the practice."]},"advanced-native-1968-v2-reply":{"type":"mc","answers":["The instructions stay clear, while the response to mistakes becomes less humiliating.","She distinguishes firm practice requirements from an unnecessarily harsh reaction.","For this practice, a steady hand is better than a heavy hand because clear explanation can accompany the rules.","She wants to find the misunderstanding rather than shame the learner for it."],"options":["The instructions stay clear, while the response to mistakes becomes less humiliating.","She distinguishes firm practice requirements from an unnecessarily harsh reaction.","For this practice, a steady hand is better than a heavy hand because clear explanation can accompany the rules.","She wants to find the misunderstanding rather than shame the learner for it."]},"advanced-native-1968-v1-scene":{"type":"mc","answers":["Saying a steady hand is better than a heavy hand does not rule out clear borrowing limits explained without humiliation."],"options":["The account describes the borrowing conditions being left for learners to work out after taking equipment away.","Saying a steady hand is better than a heavy hand does not rule out clear borrowing limits explained without humiliation.","The limits establish that the tutor used shame instead of an explanation."]},"advanced-native-1968-v1-contrast":{"type":"mc","answers":["說話者已比較兩種指引方式的實測後續成效。"],"options":["可以看上下文解釋兩種做法有何不同。","說話者在當時情境偏向穩定引導。","說話者已比較兩種指引方式的實測後續成效。"]},"advanced-native-1968-v1-branch":{"type":"mc","answers":["A steady hand is better than a heavy hand here: I can explain the cue clearly and ask what is unclear without shaming anyone."],"options":["I would judge the guidance only by whether everyone obeyed immediately, without asking if they understood.","A steady hand is better than a heavy hand here: I can explain the cue clearly and ask what is unclear without shaming anyone.","I thought a patient response meant leaving the drill requirements for beginners to guess."]},"advanced-native-1968-v1-final":{"type":"open","answers":["The diarist argues that a steady hand is better than a heavy hand, contrasting a patient explanation with public blame in her own training. This page records her judgement, not a comparison of the mentors’ later results.","For the writer of this diary, a steady hand is better than a heavy hand: she values the mentor who explained a mistake calmly. The exhibit presents that personal experience without claiming to establish which approach always produces better outcomes."],"options":[]}}'::jsonb),
('advanced-native-1969', '["phrase"]'::jsonb, '{"advanced-native-1969-v1-audio":{"type":"mc","answers":["The listening was enjoyable, but it displaced the planned meeting preparation until a call drew attention to the time."],"options":["The listening was enjoyable, but it displaced the planned meeting preparation until a call drew attention to the time.","The call interrupted the speaker before any enjoyable listening had begun.","The browsing stayed focused on the single song throughout, with no shift in attention.","The speaker finished the meeting preparation before opening any recording."]},"advanced-native-1969-v2-reply":{"type":"mc","answers":["I enjoyed the exploration but had not done the meeting preparation when my friend called.","I got lost in it, enjoying the recordings while losing track of the preparation I had intended.","One recording led me to another until the call reminded me about the time.","The listening held my attention more than my original plan did."],"options":["I enjoyed the exploration but had not done the meeting preparation when my friend called.","I got lost in it, enjoying the recordings while losing track of the preparation I had intended.","One recording led me to another until the call reminded me about the time.","The listening held my attention more than my original plan did."]},"advanced-native-1969-v1-scene":{"type":"mc","answers":["She can get lost in the story during chosen reading time without the account establishing that she neglected another commitment."],"options":["The account reports that she missed a meeting because she could not stop reading.","Her absorbed reading is described as an attempt to avoid an arrangement she had already made.","She can get lost in the story during chosen reading time without the account establishing that she neglected another commitment."]},"advanced-native-1969-v1-contrast":{"type":"mc","answers":["單憑這句便可確定，當事人錯過了一個已約定的會議。"],"options":["單憑這句便可確定，當事人錯過了一個已約定的會議。","上下文可能描述高度投入。","需要先知道it指甚麼活動或內容。"]},"advanced-native-1969-v1-branch":{"type":"mc","answers":["I got lost in it and enjoyed the music, but that is also why I failed to notice the time for preparing the meeting."],"options":["I thought the delay to the meeting preparation had been a conscious choice made before I started listening.","I assumed the reminder call caused the delay, rather than drawing my attention to preparation I had already neglected.","I got lost in it and enjoyed the music, but that is also why I failed to notice the time for preparing the meeting."]},"advanced-native-1969-v1-final":{"type":"open","answers":["I could easily get lost in it, and I would love to hear the recordings, but I have promised a family call at nine. Could we choose three excerpts tonight and arrange another evening for the rest?","I enjoy getting lost in the music, though tonight I need to stop for my nine o’clock call. Let us pick three recordings now and decide together when to continue, rather than try to finish the whole collection."],"options":[]}}'::jsonb),
('advanced-native-1970', '["phrase"]'::jsonb, '{"advanced-native-1970-v1-audio":{"type":"mc","answers":["Useful possibilities and a need to choose a route towards the group’s question."],"options":["Useful possibilities and a need to choose a route towards the group’s question.","The group treated the lively discussion itself as the answer, without checking the named archives.","Useful discussion spaces that the group considered a substitute for defining a research question.","The group began by opening every suggested link before choosing a question."]},"advanced-native-1970-v2-reply":{"type":"mc","answers":["The image connects valuable material with the practical difficulty of finding a relevant starting point.","The internet is a huge city in the image: varied opportunities still leave us needing a route for our question.","There is more to explore than we can use without first deciding what we want to find.","The useful archives do not remove the need to compare where a search should begin."],"options":["The image connects valuable material with the practical difficulty of finding a relevant starting point.","The internet is a huge city in the image: varied opportunities still leave us needing a route for our question.","There is more to explore than we can use without first deciding what we want to find.","The useful archives do not remove the need to compare where a search should begin."]},"advanced-native-1970-v1-scene":{"type":"mc","answers":["The internet can feel like a huge city even with useful signposts; the three routes help readers choose among different resources."],"options":["The routes show that all readers must use the same source regardless of their question.","The guide is described as removing the photographs and stories rather than organising entry points.","The internet can feel like a huge city even with useful signposts; the three routes help readers choose among different resources."]},"advanced-native-1970-v1-contrast":{"type":"mc","answers":["每一個頁面都已獲確認可靠。"],"options":["新使用者可能需要按目的選入口。","可以有多種資源及探索路線。","每一個頁面都已獲確認可靠。"]},"advanced-native-1970-v1-branch":{"type":"mc","answers":["The internet is a huge city in this comparison, so a useful link can be one starting point without being the right route for every question."],"options":["I thought a useful first link established that every member should follow the same search.","I would judge a route only by how many pages it opens, rather than whether it answers the question.","The internet is a huge city in this comparison, so a useful link can be one starting point without being the right route for every question."]},"advanced-native-1970-v1-final":{"type":"open","answers":["The internet can feel like a huge city to a researcher seeking a new route, as Ah Man found when trying to trace the song. Ah Wai’s success in a familiar photograph archive shows a different experience, not proof that every search is straightforward.","For Ah Man, the internet is a huge city with several possible routes but no clear way to compare the song sources yet. Ah Wai already knows her way around the photograph archive, so our summary should preserve their different starting points."],"options":[]}}'::jsonb),
('advanced-native-1971', '["phrase"]'::jsonb, '{"advanced-native-1971-v1-audio":{"type":"mc","answers":["An explanation of the index that helps newcomers find relevant collections."],"options":["A set of final conclusions that newcomers are expected to copy.","A search box that the newcomers have not yet been given access to.","A review of why the newcomers rejected the relevant collections after reading them.","An explanation of the index that helps newcomers find relevant collections."]},"advanced-native-1971-v2-reply":{"type":"mc","answers":["Knowing the structure can help them notice relevant collections before drawing conclusions.","We want to support their search without deciding what they should conclude.","Otherwise newcomers may wander through without a map, unsure which collections relate to their question.","The search box does not explain how the records are grouped."],"options":["Knowing the structure can help them notice relevant collections before drawing conclusions.","We want to support their search without deciding what they should conclude.","Otherwise newcomers may wander through without a map, unsure which collections relate to their question.","The search box does not explain how the records are grouped."]},"advanced-native-1971-v1-scene":{"type":"mc","answers":["Not carrying a printed map does not mean he must wander through without a map in the figurative sense; he already understands the index."],"options":["The account establishes that he has no way to identify a relevant collection.","Knowing the collection names is described as replacing his research question with somebody else’s conclusion.","Not carrying a printed map does not mean he must wander through without a map in the figurative sense; he already understands the index."]},"advanced-native-1971-v1-contrast":{"type":"mc","answers":["他們已經搜尋失敗，並決定放棄研究。"],"options":["說話者認為，他們可能缺少辨認路向的指引。","他們已經搜尋失敗，並決定放棄研究。","需要看上下文，確認through所指的環境。"]},"advanced-native-1971-v1-branch":{"type":"mc","ans