('advanced-native-2010', '["phrase"]'::jsonb, '{"advanced-native-2010-v1-audio":{"type":"mc","answers":["A later start was confirmed in the dated update, while cancellation remained unsupported."],"options":["A later start was confirmed in the dated update, while cancellation remained unsupported.","Repeated screenshots were treated as enough confirmation that the event had been cancelled.","The organiser confirmed that the original start time would remain unchanged.","The cancellation claim was traced to a named organiser before the check began."]},"advanced-native-2010-v2-reply":{"type":"mc","answers":["Repetition alone did not establish what the organiser had actually changed.","We needed to separate real information from noise rather than count how often the claim appeared.","The date and source could help us judge which timing information was current.","The cancellation claim still lacked a named source."],"options":["Repetition alone did not establish what the organiser had actually changed.","We needed to separate real information from noise rather than count how often the claim appeared.","The date and source could help us judge which timing information was current.","The cancellation claim still lacked a named source."]},"advanced-native-2010-v1-scene":{"type":"mc","answers":["Clear sound does not by itself separate real information from noise in this figurative sense; the claims still need checking."],"options":["The description concerns only the absence of background sound, so there is no need to consider the claims’ sources.","The description says the speaker checked the date with the organiser before recording.","Clear sound does not by itself separate real information from noise in this figurative sense; the claims still need checking."]},"advanced-native-2010-v1-contrast":{"type":"mc","answers":["Keep only the messages that support the conclusion one already prefers."],"options":["Keep only the messages that support the conclusion one already prefers.